const aiOutput = $input.first().json.output;
const originalData = $('Prepare Final Record').first().json;

let parsed;
try {
  parsed = JSON.parse(aiOutput);
} catch (e) {
  // If the AI added any extra text around the JSON, try to extract just the {...} part
  const match = aiOutput.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    parsed = { status: "ERROR", notes: "Could not parse AI response" };
  }
}

return [{
  json: {
    ...originalData,
    ai_validation_status: parsed.status,
    ai_notes: parsed.notes
  }
}];

const data = $input.first().json;

// Guardrails only apply while the user is actively answering a question
// ("new_session" and "complete" branches don't have user-typed answers to check)
if (data.branch !== "continue") {
  return [{ json: data }];
}

const userInput = data.answered_value || "";
const issues = [];

// Guardrail 1: Reject absurdly long input (basic abuse/spam protection)
if (userInput.length > 200) {
  issues.push("Input too long (max 200 characters)");
}

// Guardrail 2: Detect common prompt injection attempts
const injectionPatterns = [
  /ignore (previous|all|the) instructions/i,
  /you are now/i,
  /system prompt/i,
  /forget (everything|your instructions)/i,
  /act as/i
];
const looksLikeInjection = injectionPatterns.some(pattern => pattern.test(userInput));
if (looksLikeInjection) {
  issues.push("Input contains suspicious instruction-like language");
}

// Guardrail 3: Field-specific format checks
if (data.answered_field_name === "phone") {
  const digitsOnly = userInput.replace(/\D/g, "");
  if (digitsOnly.length !== 10) {
    issues.push("Phone number must be exactly 10 digits");
  }
}

if (data.answered_field_name === "email") {
  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailPattern.test(userInput)) {
    issues.push("Email format looks invalid");
  }
}

// If any guardrail failed, override the branch to re-ask the same question
if (issues.length > 0) {
  return [{
    json: {
      ...data,
      branch: "guardrail_failed",
      guardrail_issues: issues,
      reply_text: `⚠️ I couldn't accept that answer: ${issues.join(", ")}. Could you try again?\n\n${data.reply_text.includes('?') ? '' : ''}Please re-answer: ` + (data.answered_field_name ? `(same question as before)` : "")
    }
  }];
}

return [{ json: data }];
